const json=(data,status=200,extra={})=>{const headers=new Headers({"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"});for(const [key,value] of Object.entries(extra)){if(key.toLowerCase()==="set-cookie"&&Array.isArray(value))value.forEach(cookie=>headers.append("Set-Cookie",cookie));else headers.set(key,value)}return new Response(JSON.stringify(data),{status,headers})};
const text=(v,max=500)=>String(v??"").trim().slice(0,max);
const emailOK=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
const phoneOK=v=>/^\\+?[0-9 ()-]{7,20}$/.test(v);
const now=()=>new Date().toISOString();
const id=()=>crypto.randomUUID();
const b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\\+/g,"-").replace(/\\//g,"_").replace(/=+$/,"");
const unb64=s=>Uint8Array.from(atob(s.replace(/-/g,"+").replace(/_/g,"/")),c=>c.charCodeAt(0));
const randomToken=()=>b64(crypto.getRandomValues(new Uint8Array(32)));
const sha=async value=>b64(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(value)));
const passwordHash=async password=>{const salt=crypto.getRandomValues(new Uint8Array(16)),key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]),bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt,iterations:310000,hash:"SHA-256"},key,256);return "pbkdf2$310000$"+b64(salt)+"$"+b64(bits)};
const passwordVerify=async(password,stored)=>{try{const[,rounds,salt,expected]=stored.split("$"),key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]),bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:unb64(salt),iterations:Number(rounds),hash:"SHA-256"},key,256);return b64(bits)===expected}catch{return false}};
const cookies=req=>Object.fromEntries((req.headers.get("Cookie")||"").split(";").map(v=>v.trim().split(/=(.*)/s).slice(0,2)).filter(x=>x.length===2));
const cookie=(name,value,opts="")=>name+"="+value+"; Path=/; Secure; SameSite=Lax; "+opts;
const setSessionCookies=(session,csrf)=>[cookie("nooki_session",session,"HttpOnly; Max-Age=604800"),cookie("nooki_csrf",csrf,"Max-Age=604800")];
const clearCookies=["nooki_session=; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=0","nooki_csrf=; Path=/; Secure; SameSite=Lax; Max-Age=0"];
const csrfOK=req=>{const c=cookies(req);return !!c.nooki_csrf&&c.nooki_csrf===req.headers.get("X-CSRF-Token")};
const fail=(error,message,status=400)=>json({ok:false,error,message},status);
const cleanOrigin=(req,env)=>{const origin=req.headers.get("Origin");if(!origin)return true;const allowed=(env.ALLOWED_ORIGINS||new URL(req.url).origin).split(",").map(v=>v.trim());return allowed.includes(origin)};
async function validFileSignature(file){const b=new Uint8Array(await file.slice(0,12).arrayBuffer());const starts=(a)=>a.every((v,i)=>b[i]===v);if(file.type==="image/jpeg")return starts([255,216,255]);if(file.type==="image/png")return starts([137,80,78,71,13,10,26,10]);if(file.type==="image/webp")return b.length>=12&&String.fromCharCode(...b.slice(0,4))==="RIFF"&&String.fromCharCode(...b.slice(8,12))==="WEBP";if(file.type==="application/pdf")return String.fromCharCode(...b.slice(0,5))==="%PDF-";return false}
async function captcha(token,req,env){if(!env.TURNSTILE_SECRET_KEY)return env.ENVIRONMENT!=="production";if(!token)return false;const form=new FormData();form.set("secret",env.TURNSTILE_SECRET_KEY);form.set("response",token);form.set("remoteip",req.headers.get("CF-Connecting-IP")||"");try{return !!(await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify",{method:"POST",body:form}).then(r=>r.json())).success}catch{return false}}
async function rateLimit(env,key,max=8,windowSeconds=900){const t=Math.floor(Date.now()/1000),row=await env.DB.prepare("SELECT count,window_started_at FROM rate_limits WHERE bucket_key=?").bind(key).first();if(!row||t-row.window_started_at>=windowSeconds){await env.DB.prepare("INSERT INTO rate_limits(bucket_key,count,window_started_at) VALUES(?,?,?) ON CONFLICT(bucket_key) DO UPDATE SET count=excluded.count,window_started_at=excluded.window_started_at").bind(key,1,t).run();return true}if(row.count>=max)return false;await env.DB.prepare("UPDATE rate_limits SET count=count+1 WHERE bucket_key=?").bind(key).run();return true}
async function sendEmail(env,to,subject,html){if(!env.RESEND_API_KEY||!env.RESEND_FROM)return false;try{const r=await fetch("https://api.resend.com/emails",{method:"POST",headers:{"Authorization":"Bearer "+env.RESEND_API_KEY,"Content-Type":"application/json"},body:JSON.stringify({from:env.RESEND_FROM,to:[to],subject,html})});return r.ok}catch(error){console.error("Nooki verification email delivery failed",error?.message||"unknown");return false}}
async function auth(req,env){const token=cookies(req).nooki_session;if(!token)return null;const row=await env.DB.prepare("SELECT s.id session_id,s.csrf_token,s.expires_at,u.id user_id,u.email,u.display_name,u.phone,u.account_status,u.email_verified_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?").bind(await sha(token)).first();if(!row||row.expires_at<now()||row.account_status!=="active")return null;const roles=await env.DB.prepare("SELECT role FROM user_roles WHERE user_id=?").bind(row.user_id).all();return {...row,roles:(roles.results||[]).map(x=>x.role)}}
const has=(user,role)=>!!user?.roles?.includes(role);
async function requireUser(req,env){const user=await auth(req,env);if(!user)return {error:fail("authentication_required","Please sign in to continue.",401)};if(!csrfOK(req)||cookies(req).nooki_csrf!==user.csrf_token)return {error:fail("csrf_failed","Refresh the page and try again.",403)};return {user}}
