if(path==="/api/admin/spaces"&&method==="POST"){let b;try{b=await req.json()}catch{return fail("invalid_json","Request body must be JSON.")}const sid=text(b.id,80),decision=b.decision;if(!["published","rejected","suspended"].includes(decision))return fail("invalid_transition","Choose published, rejected or suspended.",422);const space=await env.DB.prepare("SELECT id FROM spaces WHERE id=?").bind(sid).first();if(!space)return fail("not_found","Space not found.",404);const stamp=now();await env.DB.prepare("UPDATE spaces SET status=?,updated_at=? WHERE id=?").bind(decision,stamp,sid).run();await env.DB.prepare("UPDATE media_assets SET status=? WHERE context_id=? AND purpose='listing' AND status='pending'").bind(decision==="published"?"approved":"rejected",sid).run();await env.DB.prepare("INSERT INTO audit_logs(actor_email,action,entity_type,entity_id,detail_json,created_at) VALUES(?,?,?,?,?,?)").bind(email,"space."+decision,"space",sid,JSON.stringify({notes:text(b.notes,500)}),stamp).run();return json({ok:true,status:decision})}
