if(path==="/api/admin/payments"&&method==="PATCH"){let b;try{b=await req.json()}catch{return fail("invalid_json","Request body must be JSON.")}const intent=await env.DB.prepare("SELECT p.*,b.status booking_status,(SELECT pc.amount FROM payment_callbacks pc WHERE pc.payment_intent_id=p.id ORDER BY pc.processed_at DESC LIMIT 1) callback_amount FROM payment_intents p JOIN bookings b ON b.id=p.booking_id WHERE p.id=?").bind(text(b.id,80)).first();if(!intent||intent.status!=="reported_success_pending_reconciliation"||!intent.provider_transaction_id||intent.result_code!=="0"||Number(intent.callback_amount)!==Number(intent.amount))return fail("payment_not_reconcilable","No successful Daraja callback is awaiting reconciliation.",409);if(b.decision!=="confirm"&&b.decision!=="reject")return fail("invalid_decision","Choose confirm or reject.",422);const stamp=now();if(b.decision==="confirm"){await env.DB.batch([env.DB.prepare("UPDATE payment_intents SET status='paid',paid_at=?,updated_at=? WHERE id=?").bind(stamp,stamp,intent.id),env.DB.prepare("UPDATE bookings SET status='confirmed',confirmed_at=?,updated_at=? WHERE id=? AND status='awaiting_payment'").bind(stamp,stamp,intent.booking_id),env.DB.prepare("INSERT INTO audit_logs(actor_email,action,entity_type,entity_id,detail_json,created_at) VALUES(?,?,?,?,?,?)").bind(email,"payment.manually_reconciled","payment",intent.id,JSON.stringify({receipt:intent.provider_transaction_id}),stamp)]);await event(env,intent.booking_id,"payment.reconciled",null,{payment_intent_id:intent.id});return json({ok:true,status:"paid",booking_status:"confirmed"})}await env.DB.batch([env.DB.prepare("UPDATE payment_intents SET status='failed',updated_at=? WHERE id=?").bind(stamp,intent.id),env.DB.prepare("UPDATE bookings SET status='accepted',updated_at=? WHERE id=? AND status='awaiting_payment'").bind(stamp,intent.booking_id),env.DB.prepare("INSERT INTO audit_logs(actor_email,action,entity_type,entity_id,detail_json,created_at) VALUES(?,?,?,?,?,?)").bind(email,"payment.reconciliation_rejected","payment",intent.id,JSON.stringify({reason:text(b.notes,500)}),stamp)]);return json({ok:true,status:"failed",booking_status:"accepted"})}
