export default{async fetch(request,env){const url=new URL(request.url);let response;if(url.pathname.startsWith("/api/")){try{response=await handle(request,env,url)}catch(error){console.error("Nooki API error",error?.message||"unknown");response=fail("internal_error","Something went wrong. Please try again.",500)}}else{response=await env.ASSETS.fetch(request);if(response.status===404&&request.method==="GET"&&!url.pathname.split("/").pop().includes("."))response=await env.ASSETS.fetch(new Request(new URL("/index.html",url),request))}const headers=new Headers(response.headers);headers.set("X-Content-Type-Options","nosniff");headers.set("Referrer-Policy","strict-origin-when-cross-origin");headers.set("Permissions-Policy","camera=(), microphone=(), geolocation=()");headers.set("Content-Security-Policy","default-src 'self'; img-src 'self' https: data:; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; script-src 'self' https://challenges.cloudflare.com; connect-src 'self' https://challenges.cloudflare.com; frame-src https://challenges.cloudflare.com; base-uri 'self'; form-action 'self'; frame-ancestors 'none'");return new Response(response.body,{status:response.status,statusText:response.statusText,headers})},async scheduled(controller,env,ctx){if(!env.DB)return;const stamp=now(),cutoff=Math.floor(Date.now()/1000)-86400;ctx.waitUntil(Promise.all([env.DB.prepare("DELETE FROM sessions WHERE expires_at < ?").bind(stamp).run(),env.DB.prepare("DELETE FROM email_verification_tokens WHERE expires_at < ? OR consumed_at IS NOT NULL").bind(stamp).run(),env.DB.prepare("DELETE FROM rate_limits WHERE window_started_at < ?").bind(cutoff).run(),env.DB.prepare("DELETE FROM upload_intents WHERE expires_at < ?").bind(stamp).run()]))}};
